#include <vector>
#include <cstddef>
#include <omp.h>

void luFactorize(std::vector<double> &A, size_t N) {
    // In-place Doolittle LU without pivoting:
    // A(i,k) (i>k) becomes L(i,k); diagonal of L is 1 (not stored).
    // A(k,j) (j>=k) becomes U(k,j).
    if (N == 0) return;

    for (size_t k = 0; k < N; ++k) {
        const double pivot = A[k * N + k];

        // No pivoting: if pivot == 0, division will produce inf/NaN.
        // Caller is responsible for providing a matrix suitable for no-pivot LU.

        // Compute multipliers L(i,k) for rows below pivot
        #pragma omp parallel for schedule(static)
        for (std::ptrdiff_t i_ = static_cast<std::ptrdiff_t>(k + 1);
             i_ < static_cast<std::ptrdiff_t>(N); ++i_) {
            const size_t i = static_cast<size_t>(i_);
            A[i * N + k] /= pivot; // L(i,k)
        }

        // Update trailing submatrix: A(i,j) -= L(i,k) * U(k,j)
        #pragma omp parallel for schedule(static)
        for (std::ptrdiff_t i_ = static_cast<std::ptrdiff_t>(k + 1);
             i_ < static_cast<std::ptrdiff_t>(N); ++i_) {
            const size_t i = static_cast<size_t>(i_);
            const double lik = A[i * N + k];
            const size_t row_i = i * N;
            const size_t row_k = k * N;
            for (size_t j = k + 1; j < N; ++j) {
                A[row_i + j] -= lik * A[row_k + j];
            }
        }
    }
}
